insert into public.environment_reports (
  id,
  title,
  latitude,
  longitude,
  dirtiness_score,
  waste_type,
  issue_type,
  severity,
  notes,
  status,
  observed_at,
  created_at
)
select
  id,
  title,
  latitude,
  longitude,
  dirtiness_score,
  waste_type::public.environment_waste_type,
  issue_type,
  severity,
  notes,
  'APPROVED'::public.report_status,
  now() - age,
  now() - age
from heatmap_reports
on conflict (id) do update set
  title = excluded.title,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  dirtiness_score = excluded.dirtiness_score,
  waste_type = excluded.waste_type,
  issue_type = excluded.issue_type,
  severity = excluded.severity,
  notes = excluded.notes,
  status = excluded.status,
  observed_at = excluded.observed_at;
